        ITEMS.put("Sprout of Anguish +3", new NBTItemstackAPItem(Items.COMMAND_BLOCK, 1, "{Name:'{\"text\":\"Sprout of Anguish +3\",\"color\":\"dark_red\",\"italic\":false,\"underlined\":true}',Lore:['{\"text\":\"\\\\\"Ah, Ael Irien... do you know what\"}','{\"text\":\"suffering you have inflicted upon\"}','{\"text\":\"this realm? Your greatest sin, felt\"}','{\"text\":\"by all souls, millennia later. You hide\"}','{\"text\":\"behind a curtain, concealing your\"}','{\"text\":\"true wickedness. You are cowardice\"}','{\"text\":\"incarnate.\\\\\"\"}','{\"text\":\" \"}','{\"text\":\"When in offhand:\",\"color\":\"gray\",\"italic\":false}','{\"text\":\"+10 Max Health\",\"color\":\"blue\",\"italic\":false}','{\"text\":\" \"}','{\"text\":\"Relic\",\"color\":\"dark_red\",\"italic\":false}']},HideFlags:6,Unbreakable:1b,AttributeModifiers:[{AttributeName:\"generic.max_health\",Name:\"generic.max_health\",Amount:10,Operation:0,UUID:[I;331558246,1136741372,-1724593376,-1379418751],Slot:\"offhand\"}]}"));
